(async () => {
  const { existsSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist');
  const headersEnv = process.env.HEADERS;
  let headers = null;
  if (headersEnv) {
    try { headers = JSON.parse(headersEnv); }
    catch { throw new Error('HEADERS must be JSON array'); }
    if (!Array.isArray(headers)) throw new Error('HEADERS must be array');
  }
  globalThis.tsvInputPath = inputPath;
  globalThis.tsvOutputPath = outputPath;
  globalThis.tsvHeaders = headers;
})();

(async () => {
  const mod = await import('tsvtojson');
  const tsvtojson = mod.default || mod;
  if (typeof tsvtojson !== 'function') throw new Error('tsvtojson export not a function');
  const data = await tsvtojson(globalThis.tsvInputPath, globalThis.tsvHeaders);
  globalThis.tsvData = data;
})();

(async () => {
  const data = globalThis.tsvData;
  if (data === undefined) throw new Error('No data to emit');
  const jsonStr = JSON.stringify(data);
  const { writeFileSync } = await import('node:fs');
  writeFileSync(globalThis.tsvOutputPath, jsonStr);
  console.log(JSON.stringify({ json: jsonStr }));
})();
